parser->m_parseEndByteIndex += len;
parser->m_positionPtr = s;
parser->m_parsingStatus.finalBuffer = (XML_Bool)isFinal;

parser->m_errorCode
    = callProcessor(parser, s, parser->m_parseEndPtr = s + len, &end);

