			e_loc = strchr(tok->pb->buf, 'E');
		if (e_loc)
		{
			char *last_saved_char =
			    &tok->pb->buf[printbuf_length(tok->pb) - 1];
			is_exponent = 1;
			/* If the "e" isn't at the end, we can't start with a '-' */
			if (e_loc != last_saved_char)
				negativesign_next_possible_location = -1;
			// else leave it set to 1, i.e. start of the new input
		}
	}

if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
{
	printbuf_memappend_fast(tok->pb, case_start, case_len);
	goto out;

void
BaseInit(void)
{
	/*
	 * Attach to shared memory and semaphores, and initialize our
	 * input/output/debugging file descriptors.
	 */
	InitCommunication();
	DebugFileOpen();

	/* Do local initialization of file, storage and buffer managers */
	InitFileAccess();
	InitSync();
	smgrinit();
	InitBufferPoolAccess();
}

static void
InitCommunication(void)
{
	/*
	 * initialize shared memory and semaphores appropriately.
	 */
	if (!IsUnderPostmaster)		/* postmaster already did this */
	{
		/*
		 * We're running a postgres bootstrap process or a standalone backend,
		 * so we need to set up shmem.
		 */
		CreateSharedMemoryAndSemaphores();
	}
}

/*
 * bufmgr needs another initialization call too
 */
InitBufferPoolBackend();

/*
 * ProcGlobal should be set up already (if we are a backend, we inherit
 * this by fork() or EXEC_BACKEND mechanism from the postmaster).
 */
if (ProcGlobal == NULL)
	elog(PANIC, "proc header uninitialized");

if (MyProc != NULL)
	elog(ERROR, "you already exist");

/* Decide which list should supply our PGPROC. */
if (IsAnyAutoVacuumProcess())
	procgloballist = &ProcGlobal->autovacFreeProcs;
else if (IsBackgroundWorker)
	procgloballist = &ProcGlobal->bgworkerFreeProcs;
else if (am_walsender)
	procgloballist = &ProcGlobal->walsenderFreeProcs;
else
	procgloballist = &ProcGlobal->freeProcs;

/*
 * Try to get a proc struct from the appropriate free list.  If this
 * fails, we must be out of PGPROC structures (not to mention semaphores).
 *
 * While we are holding the ProcStructLock, also copy the current shared
 * estimate of spins_per_delay to local storage.
 */
SpinLockAcquire(ProcStructLock);

set_spins_per_delay(ProcGlobal->spins_per_delay);

MyProc = *procgloballist;

if (MyProc != NULL)
{
	*procgloballist = (PGPROC *) MyProc->links.next;
	SpinLockRelease(ProcStructLock);

 * Set up process table
 */
if (!IsUnderPostmaster)
	InitProcGlobal();

void
BaseInit(void)
{
	Assert(MyProc != NULL);

	/*
	 * Initialize our input/output/debugging file descriptors.
	 */
	DebugFileOpen();

	/* Do local initialization of file, storage and buffer managers */
	InitFileAccess();
	InitSync();
	smgrinit();
	InitBufferPoolAccess();
}

void
InitBufferPoolAccess(void)
{
	HASHCTL		hash_ctl;

	memset(&PrivateRefCountArray, 0, sizeof(PrivateRefCountArray));

	hash_ctl.keysize = sizeof(int32);
	hash_ctl.entrysize = sizeof(PrivateRefCountEntry);

	PrivateRefCountHash = hash_create("PrivateRefCount", 100, &hash_ctl,
									  HASH_ELEM | HASH_BLOBS);

	/*
	 * AtProcExit_Buffers needs LWLock access, and thereby has to be called at
	 * the corresponding phase of backend shutdown.
	 */
	Assert(MyProc != NULL);
	on_shmem_exit(AtProcExit_Buffers, 0);
}

elog(DEBUG3, "InitPostgres");

/*
 * Add my PGPROC struct to the ProcArray.
 *
 * Once I have done this, I am visible to other backends!
 */
InitProcessPhase2();

 * Set up process table
 */
if (!IsUnderPostmaster)
	InitProcGlobal();

/*
 * ProcGlobal should be set up already (if we are a backend, we inherit
 * this by fork() or EXEC_BACKEND mechanism from the postmaster).
 */
if (ProcGlobal == NULL)
	elog(PANIC, "proc header uninitialized");

if (MyProc != NULL)
	elog(ERROR, "you already exist");

/* Decide which list should supply our PGPROC. */
if (IsAnyAutoVacuumProcess())
	procgloballist = &ProcGlobal->autovacFreeProcs;
else if (IsBackgroundWorker)
	procgloballist = &ProcGlobal->bgworkerFreeProcs;
else if (am_walsender)
	procgloballist = &ProcGlobal->walsenderFreeProcs;
else
	procgloballist = &ProcGlobal->freeProcs;

/*
 * Try to get a proc struct from the appropriate free list.  If this
 * fails, we must be out of PGPROC structures (not to mention semaphores).
 *
 * While we are holding the ProcStructLock, also copy the current shared
 * estimate of spins_per_delay to local storage.
 */
SpinLockAcquire(ProcStructLock);

set_spins_per_delay(ProcGlobal->spins_per_delay);

MyProc = *procgloballist;

if (MyProc != NULL)
{
	*procgloballist = (PGPROC *) MyProc->links.next;
	SpinLockRelease(ProcStructLock);

		/* Initialize MaxBackends (if under postmaster, was done already) */
		InitializeMaxBackends();

		CreateSharedMemoryAndSemaphores();
	}

	/*
	 * Create a per-backend PGPROC struct in shared memory, except in the
	 * EXEC_BACKEND case where this was done in SubPostmasterMain. We must do
	 * this before we can use LWLocks (and in the EXEC_BACKEND case we already
	 * had to do some stuff with LWLocks).
	 */
#ifdef EXEC_BACKEND
	if (!IsUnderPostmaster)
		InitProcess();
#else
	InitProcess();
#endif

	/* Early initialization */
	BaseInit();

	/* We need to allow SIGINT, etc during the initial transaction */
	PG_SETMASK(&UnBlockSig);

	/*
	 * General initialization.
	 *
	 * NOTE: if you are tempted to add code in this vicinity, consider putting
	 * it inside InitPostgres() instead.  In particular, anything that
	 * involves database access should be there, not here.
	 */
	InitPostgres(dbname, InvalidOid, username, InvalidOid, NULL, false);

/* ---- Callout with numerical or string argument ---- */

case CHAR_C:
if (++ptr >= ptrend) goto UNCLOSED_PARENTHESIS;

/* If the previous item was a condition starting (?(? an assertion,
optionally preceded by a callout, is expected. This is checked later on,
during actual compilation. However we need to identify this kind of
assertion in this pass because it must not be qualified. The value of
expect_cond_assert is set to 2 after (?(? is processed. We decrement it
for a callout - still leaving a positive value that identifies the
assertion. Multiple callouts or any other items will make it zero or
less, which doesn't matter because they will cause an error later. */

expect_cond_assert = prev_expect_cond_assert - 1;

/* ---- Callout with numerical or string argument ---- */

case CHAR_C:
if ((xoptions & PCRE2_EXTRA_NEVER_CALLOUT) != 0)
  {
  errorcode = ERR103;
  goto FAILED;
  }

pcre2_compile_context PRIV(default_compile_context) = {
  { default_malloc, default_free, NULL },    /* Default memory handling */
  NULL,                                      /* Stack guard */
  NULL,                                      /* Stack guard data */
  PRIV(default_tables),                      /* Character tables */
  PCRE2_UNSET,                               /* Max pattern length */
  PCRE2_UNSET,                               /* Max pattern compiled length */
  BSR_DEFAULT,                               /* Backslash R default */
  NEWLINE_DEFAULT,                           /* Newline convention */
  PARENS_NEST_LIMIT,                         /* As it says */
  0,                                         /* Extra options */
  MAX_VARLOOKBEHIND,                         /* As it says */
  PCRE2_OPTIMIZATION_ALL                     /* All optimizations enabled */
  };

/* The create function copies the default into the new memory, but must
override the default memory handling functions if a gcontext was provided. */

PCRE2_EXP_DEFN pcre2_compile_context * PCRE2_CALL_CONVENTION
pcre2_compile_context_create(pcre2_general_context *gcontext)
{
pcre2_compile_context *ccontext = PRIV(memctl_malloc)(
  sizeof(pcre2_real_compile_context), (pcre2_memctl *)gcontext);
if (ccontext == NULL) return NULL;
*ccontext = PRIV(default_compile_context);
if (gcontext != NULL)
  *((pcre2_memctl *)ccontext) = *((pcre2_memctl *)gcontext);
return ccontext;

PCRE2_EXP_DEFN int PCRE2_CALL_CONVENTION
pcre2_set_compile_extra_options(pcre2_compile_context *ccontext, uint32_t options)
{
ccontext->extra_options = options;
return 0;
}
